import{_ as a,o as t,c as e,a3 as _}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/106-如何利用安全型法则？.md","filePath":"books/attached/106-如何利用安全型法则？.md","lastUpdated":1794316978000}'),l={name:"books/attached/106-如何利用安全型法则？.md"};function o(i,p,r,s,d,n){return t(),e("div",null,[...p[0]||(p[0]=[_('<h3 id="如何利用安全型法则" tabindex="-1">如何利用安全型法则？ <a class="header-anchor" href="#如何利用安全型法则" aria-label="Permalink to &quot;如何利用安全型法则？&quot;">​</a></h3><p>非安全型的臆测会干扰冲突的解决。尤其是仅仅关注自己的需求与痛苦，更是容易带来麻烦。人们总会担心对方不能和自己感同身受，担心对方不如自己那么乐于亲近，这是情有可原的。但是在冲突中受到这些想法的影响，事情就会非常糟糕。因此身陷冲突的时候，下面的事实需要牢记心中。</p><ul><li><p>仅仅一场争吵，并不会摧毁亲密关系。</p></li><li><p>大胆表达你的担心！别让无谓的担忧缚住手脚。如果你害怕对方拒绝你，也请大胆告诉对方。</p></li><li><p>别一味觉得对方心情糟糕是你造成的。或许根本不关你的事。</p></li><li><p>大胆表达出你的需求，相信你的伴侣会在乎与回应你。</p></li><li><p>别指望对方会猜到你的心思。只要你不开诚布公告诉他，别人永远不会知道的。</p></li><li><p>别一味揣测对方话语的隐含意思，有所怀疑的话，就开口问吧。</p></li></ul><p>下面是一些常规的建议：在争吵中，将事情往好的方面想是最好的。事实上，做最坏的打算是非安全型依恋风格的典型思维方式，这往往又会表现为一种自证预言。若是你猜测对方肯定会伤害你，拒绝你，你就会条件反射般地产生防御性的回应——而消极因子就会引起恶性循环。即使你必须得一直提醒自己相信前面提到的“积极真理”（因为一开始你是半信半疑的），这仍然有积极效用。在大多数情况下，这些积极的想法，能让你们的对方调转为对的方向。</p><p>总体来说，在冲突中你得改掉这些习惯：</p><p>须规避的非安全型冲突策略</p><p>1.偏离主要问题。</p><p>2.不注重有效地表达感受与需求。</p><p>3.反复地人身攻击，诋毁对方。</p><p>4.针尖对麦芒地互相揭露对方的缺点。</p><p>5.逃避责任。</p><p>6.忽视对方的幸福感受。</p><p>保罗与杰基的冲突显然是亲密导向型而非基本生计型。这个案例可以轻而易举地阐明上面清单中所列的，几乎所有小摩擦中的禁忌行为。纵使他们深爱着对方，但（第1条）他们很轻易就绕开了真正的问题（“你父亲很不爽我说起自家的孩子……”）；（第2条）他们很显然从来不会有效地表达自己的需求和感受，他们把很多东西都藏着掖着，特别是杰基；（第3条）她对于保罗通过其他的方式向她表示亲近，采取了情感上的逃避。他们沉默了几周（第5条）后最终说开，却表现得针锋相对（第4条）。两个人都互不让步，依然不断强调自己的感受，（第6条）更加不愿意考虑对方的感受。这种坏习惯贯穿了他们的整段关系，尤其表现在双方争吵的时刻。</p>',13)])])}const m=a(l,[["render",o]]);export{h as __pageData,m as default};
